import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 12;
    static final int INF = 1000000;
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};
    static int N, T;
    static char[][] grid1 = new char[MAXN][MAXN];
    static char[][] grid2 = new char[MAXN][MAXN];
    static int[][] A = new int[MAXN][MAXN];
    static int[][][][] B = new int[MAXN][MAXN][MAXN][MAXN];

    static class Edge {
        int a, b, cap, flow;
        public Edge(int a, int b, int cap, int flow) {
            this.a = a;
            this.b = b;
            this.cap = cap;
            this.flow = flow;
        }
    }

    static int totalNodes, sourceNode, sinkNode;
    static int[] distArr, ptrArr, qArr;
    static List<Edge> edgeList;
    static List<Integer>[] adj;

    static void addEdge(int a, int b, int cap) {
        Edge e1 = new Edge(a, b, cap, 0);
        Edge e2 = new Edge(b, a, 0, 0);
        adj[a].add(edgeList.size()); edgeList.add(e1);
        adj[b].add(edgeList.size()); edgeList.add(e2);
    }

    static boolean bfs() {
        int front = 0, back = 0;
        qArr[back++] = sourceNode;
        Arrays.fill(distArr, -1);
        distArr[sourceNode] = 0;
        while (front < back && distArr[sinkNode] == -1) {
            int v = qArr[front++];
            for (int id : adj[v]) {
                Edge e = edgeList.get(id);
                int to = e.b;
                if (distArr[to] == -1 && e.flow < e.cap) {
                    qArr[back++] = to;
                    distArr[to] = distArr[v] + 1;
                }
            }
        }
        return distArr[sinkNode] != -1;
    }

    static int pushFlow(int v, int flow) {
        if (v == sinkNode) return flow;
        for (; ptrArr[v] < adj[v].size(); ptrArr[v]++) {
            int id = adj[v].get(ptrArr[v]);
            Edge e = edgeList.get(id);
            int to = e.b;
            if (distArr[to] == distArr[v] + 1 && e.flow < e.cap) {
                int pushed = Math.min(flow, e.cap - e.flow);
                int pushedFlow = pushFlow(to, pushed);
                if (pushedFlow > 0) {
                    e.flow += pushedFlow;
                    edgeList.get(id ^ 1).flow -= pushedFlow;
                    return pushedFlow;
                }
            }
        }
        return 0;
    }

    static int computeMaxFlow() {
        int totalFlow = 0;
        while (bfs()) {
            Arrays.fill(ptrArr, 0);
            int pushed;
            while ((pushed = pushFlow(sourceNode, INF)) > 0) {
                totalFlow += pushed;
            }
        }
        return totalFlow;
    }

    static int getID(int x, int y) {
        return x * N + y;
    }

    static void setupNetwork() {
        sourceNode = 0;
        sinkNode = 2 * N * N + 1;
        totalNodes = 2 * N * N + 2;
        for (int i = 0; i < totalNodes; i++) {
            adj[i] = new ArrayList<>();
        }
        edgeList = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (grid1[i][j] > '0' && grid1[i][j] <= '9') {
                    addEdge(sourceNode, 1 + getID(i, j), grid1[i][j] - '0');
                }
                if (grid2[i][j] > '0' && grid2[i][j] <= '9') {
                    addEdge(N * N + 1 + getID(i, j), sinkNode, grid2[i][j] - '0');
                }
            }
        }
        for (int x1 = 0; x1 < N; x1++) {
            for (int y1 = 0; y1 < N; y1++) {
                for (int x2 = 0; x2 < N; x2++) {
                    for (int y2 = 0; y2 < N; y2++) {
                        if (B[x1][y1][x2][y2] != 0) {
                            addEdge(1 + getID(x1, y1), N * N + 1 + getID(x2, y2), INF);
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());
        for (int i = 0; i < N; i++) {
            grid1[i] = br.readLine().toCharArray();
        }
        for (int i = 0; i < N; i++) {
            grid2[i] = br.readLine().toCharArray();
        }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                A[i][j] = INF;
            }
        }
        Queue<int[]> Q = new LinkedList<>();
        for (int x = 0; x < N; x++) {
            for (int y = 0; y < N; y++) {
                if (grid1[x][y] == 'Z') {
                    for (int i = 0; i < 4; i++) {
                        int nx = x + dx[i], ny = y + dy[i];
                        if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y') {
                            A[nx][ny] = 1;
                            Q.offer(new int[]{nx, ny});
                        }
                    }
                }
            }
        }
        while (!Q.isEmpty()) {
            int[] p = Q.poll();
            int x = p[0], y = p[1];
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y' && grid1[nx][ny] != 'Z' && A[nx][ny] == INF) {
                    A[nx][ny] = A[x][y] + 1;
                    Q.offer(new int[]{nx, ny});
                }
            }
        }
        for (int x1 = 0; x1 < N; x1++) {
            for (int y1 = 0; y1 < N; y1++) {
                for (int x2 = 0; x2 < N; x2++) {
                    for (int y2 = 0; y2 < N; y2++) {
                        if (grid1[x1][y1] == 'Y' || grid1[x1][y1] == 'Z' || grid1[x2][y2] == 'Y' || grid1[x2][y2] == 'Z') {
                            B[x1][y1][x2][y2] = 0;
                            continue;
                        }
                        for (int i = 0; i < N; i++) {
                            for (int j = 0; j < N; j++) {
                                A[i][j] = INF;
                            }
                        }
                        Queue<int[]> Q2 = new LinkedList<>();
                        A[x1][y1] = 0;
                        Q2.offer(new int[]{x1, y1});
                        int c = 0;
                        while (!Q2.isEmpty()) {
                            int[] p2 = Q2.poll();
                            int x = p2[0], y = p2[1];
                            if (x == x2 && y == y2) {
                                c = 1;
                                break;
                            }
                            if (A[x][y] >= T || A[x][y] >= A[x][y]) continue;
                            for (int i = 0; i < 4; i++) {
                                int nx = x + dx[i], ny = y + dy[i];
                                if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y' && grid1[nx][ny] != 'Z' && A[nx][ny] == INF && A[x][y] + 1 <= A[nx][ny]) {
                                    A[nx][ny] = A[x][y] + 1;
                                    Q2.offer(new int[]{nx, ny});
                                }
                            }
                        }
                        B[x1][y1][x2][y2] = c;
                    }
                }
            }
        }
        setupNetwork();
        System.out.println(computeMaxFlow());
    }
}
